use std::fs

struct Bst {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
}

impl Bst {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur != -1 {
            let k = self.keys[cur]
            if x == k {
                return true
            }
            if x < k {
                cur = self.left[cur]
            } else {
                cur = self.right[cur]
            }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.contains(x) {
            return false
        }
        let id = self.keys.len()
        self.keys.push(x)
        self.left.push(-1)
        self.right.push(-1)
        if self.root == -1 {
            self.root = id
            return true
        }
        let mut cur = self.root
        let mut going = true
        while going {
            if x < self.keys[cur] {
                if self.left[cur] == -1 {
                    self.left[cur] = id
                    going = false
                } else {
                    cur = self.left[cur]
                }
            } else {
                if self.right[cur] == -1 {
                    self.right[cur] = id
                    going = false
                } else {
                    cur = self.right[cur]
                }
            }
        }
        true
    }

    fn replace_child(self, parent: int, old: int, new: int) {
        if parent == -1 {
            self.root = new
        } else if self.left[parent] == old {
            self.left[parent] = new
        } else {
            self.right[parent] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut cur = self.root
        let mut parent = -1
        while cur != -1 && self.keys[cur] != x {
            parent = cur
            if x < self.keys[cur] {
                cur = self.left[cur]
            } else {
                cur = self.right[cur]
            }
        }
        if cur == -1 {
            return false
        }
        if self.left[cur] != -1 && self.right[cur] != -1 {
            let mut sp = cur
            let mut s = self.right[cur]
            while self.left[s] != -1 {
                sp = s
                s = self.left[s]
            }
            self.keys[cur] = self.keys[s]
            let r = self.right[s]
            self.replace_child(sp, s, r)
        } else {
            let child = if self.left[cur] != -1 { self.left[cur] } else { self.right[cur] }
            self.replace_child(parent, cur, child)
        }
        true
    }

    fn height_of(self, n: int) -> int {
        if n == -1 {
            return 0
        }
        let a = self.height_of(self.left[n])
        let b = self.height_of(self.right[n])
        if a > b { a + 1 } else { b + 1 }
    }

    fn inorder(self) -> string {
        if self.root == -1 {
            return "<empty>"
        }
        let mut out: Vec<string> = []
        let mut stack: Vec<int> = []
        let mut cur = self.root
        while cur != -1 || stack.len() > 0 {
            while cur != -1 {
                stack.push(cur)
                cur = self.left[cur]
            }
            let n = stack.pop().unwrap_or(-1)
            out.push("${self.keys[n]}")
            cur = self.right[n]
        }
        out.join(" ")
    }

    fn min(self) -> string {
        if self.root == -1 {
            return "empty"
        }
        let mut cur = self.root
        while self.left[cur] != -1 {
            cur = self.left[cur]
        }
        "${self.keys[cur]}"
    }

    fn max(self) -> string {
        if self.root == -1 {
            return "empty"
        }
        let mut cur = self.root
        while self.right[cur] != -1 {
            cur = self.right[cur]
        }
        "${self.keys[cur]}"
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Bst { keys: [], left: [], right: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let arg = if parts.len() > 1 { parts[1].parse::<int>().unwrap_or(0) } else { 0 }
        if cmd == "insert" {
            if t.insert(arg) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            if t.contains(arg) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if t.delete(arg) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height_of(t.root)}")
        } else if cmd == "min" {
            println(t.min())
        } else if cmd == "max" {
            println(t.max())
        }
    }
}

